const body = $('Receive Claim').first().json.body || {};
const claim = String(body.claim ?? '').trim();
if (!claim) { throw new Error('claim_required'); }

const validDomains = ['general','healthcare','cybersecurity','ai_research','finance'];

// Parse Analyze Claim (OpenRouter Chat Completions) output into a structured object
let analysis = {};
try {
  const resp = $('Analyze Claim').first().json || {};
  let content = '';
  if (resp.choices && resp.choices[0] && resp.choices[0].message) {
    content = resp.choices[0].message.content;
  }
  if (content && typeof content === 'object') {
    analysis = content;
  } else if (typeof content === 'string' && content.trim()) {
    const s = content.trim().replace(/^```(?:json)?/i, '').replace(/```$/,'').trim();
    analysis = JSON.parse(s);
  }
} catch (e) { analysis = {}; }

let domain = String(analysis.domain ?? body.domain ?? 'general').trim().toLowerCase().replace(/[\s-]+/g,'_');
if (!validDomains.includes(domain)) { domain = 'general'; }

const retrievalMode = ['hybrid','primary_only','tavily_only'].includes(body.retrieval_mode) ? body.retrieval_mode : 'hybrid';
const forceTavily = Boolean(body.force_tavily ?? false);
const maxResults = Number.isFinite(Number(body.max_results)) ? Math.max(1, Math.min(20, Number(body.max_results))) : 5;
const requestId = String(body.request_id ?? '').trim() || ('n8n-' + Date.now() + '-' + Math.random().toString(36).slice(2,8));

const normalizedClaim = String(analysis.normalized_claim ?? claim).replace(/\s+/g,' ').trim();

let queries = Array.isArray(analysis.queries) ? analysis.queries.filter(q => typeof q === 'string' && q.trim()).map(q => q.trim()) : [];
if (!queries.length) { queries = [normalizedClaim]; }
queries = queries.slice(0,3);

const entities = Array.isArray(analysis.entities) ? analysis.entities.filter(x => typeof x === 'string' && x.trim()) : [];
const timeSensitive = Boolean(analysis.time_sensitive ?? false);

const runPrimary = retrievalMode !== 'tavily_only';

return [{ json: {
  request_id: requestId,
  claim,
  normalized_claim: normalizedClaim,
  domain,
  domain_is_routing_only: true,
  queries,
  entities,
  time_sensitive: timeSensitive,
  retrieval_mode: retrievalMode,
  force_tavily: forceTavily,
  max_results: maxResults,
  run_primary: runPrimary,
  t_start: Date.now(),
  workflow_version: '2.0.0',
} }];

const ctx = $('Build Context').first().json;
const claim = ctx.normalized_claim || ctx.claim || "";
const nowIso = new Date().toISOString();
function clean(s){ return (s||"").toString().replace(/<[^>]+>/g," ").replace(/\s+/g," ").trim(); }
const claimTokens = claim.toLowerCase().split(/[^a-z0-9]+/).filter(w => w.length > 2);
function adapterScore(text){
  const t = (text||"").toLowerCase();
  if(!claimTokens.length) return null;
  let hit = 0; const seen = {};
  for(const w of claimTokens){ if(!seen[w]){ seen[w]=1; if(t.indexOf(w) !== -1) hit++; } }
  const uniq = Object.keys(seen).length;
  return uniq ? Math.round((hit/uniq)*100)/100 : null;
}
const evidence = [];
const attempted = [];
function add(source, source_id, title, url, snippet, method, published_at){
  const snip = clean(snippet).slice(0, 800);
  if(!url && !snip) return;
  evidence.push({
    source, source_type: "PRIMARY", source_id: source_id || "",
    title: clean(title), url: url || "", snippet: snip,
    published_at: published_at || null, query_used: claim,
    retrieval_method: method, adapter_score: adapterScore(title + " " + snippet),
    retrieved_at: nowIso, retrieval_status: "success"
  });
}
// Wikipedia
try {
  const arr = (($('Wikipedia Search').first().json.query)||{}).search || [];
  if(arr.length !== undefined) attempted.push("wikipedia");
  for(const r of arr){
    const url = "https://en.wikipedia.org/wiki/" + encodeURIComponent(String(r.title||"").replace(/ /g,"_"));
    add("wikipedia", "PAGEID:"+(r.pageid||""), r.title, url, r.snippet, "wikipedia_api_search");
  }
} catch(e) {}
// PubMed
try {
  const res = ($('PubMed Summary').first().json.result)||{};
  const uids = res.uids || [];
  attempted.push("pubmed");
  for(const uid of uids){
    const rec = res[uid]; if(!rec) continue;
    const url = "https://pubmed.ncbi.nlm.nih.gov/" + uid + "/";
    const snip = (rec.title||"") + " (" + (rec.source||"") + ", " + (rec.pubdate||"") + ")";
    add("pubmed", "PMID:"+uid, rec.title, url, snip, "pubmed_esearch_efetch", rec.pubdate||null);
  }
} catch(e) {}
// OpenFDA
try {
  const results = ($('OpenFDA Search').first().json.results)||[];
  attempted.push("openfda");
  for(const r of results){
    const of = r.openfda || {};
    const id = (of.spl_id && of.spl_id[0]) || (r.id) || "";
    const name = (of.brand_name && of.brand_name[0]) || (of.generic_name && of.generic_name[0]) || "FDA drug label";
    const snipParts = [];
    if(r.indications_and_usage) snipParts.push(String(r.indications_and_usage[0]||""));
    if(r.purpose) snipParts.push(String(r.purpose[0]||""));
    const url = id ? ("https://labels.fda.gov/#search?query="+encodeURIComponent(name)) : "https://open.fda.gov/apis/drug/label/";
    add("openfda", "SPL:"+id, name + " (FDA label)", url, snipParts.join(" "), "openfda_drug_label");
  }
} catch(e) {}
// NVD
try {
  const vs = ($('NVD CVE Search').first().json.vulnerabilities)||[];
  attempted.push("nvd");
  for(const v of vs){
    const cve = v.cve || {}; const id = cve.id || "";
    const d = (cve.descriptions||[]).find(x => x.lang === "en");
    const url = id ? ("https://nvd.nist.gov/vuln/detail/"+id) : "";
    add("nvd", id, id, url, d ? d.value : "", "nvd_cve_api", (cve.published||null));
  }
} catch(e) {}
// arXiv (Atom XML)
try {
  const it = $('arXiv Search').first().json;
  const xml = (it && (it.data || it.body)) ? (it.data || it.body) : "";
  if(xml) attempted.push("arxiv");
  const entries = String(xml).split("<entry>").slice(1);
  for(const en of entries){
    const t = (en.match(/<title>([\s\S]*?)<\/title>/)||[])[1] || "";
    const sum = (en.match(/<summary>([\s\S]*?)<\/summary>/)||[])[1] || "";
    const idm = (en.match(/<id>([\s\S]*?)<\/id>/)||[])[1] || "";
    const pub = (en.match(/<published>([\s\S]*?)<\/published>/)||[])[1] || null;
    add("arxiv", idm.trim(), t, idm.trim(), sum, "arxiv_atom_api", pub);
  }
} catch(e) {}
// SEC EDGAR
try {
  const j = $('SEC EDGAR Search').first().json;
  const hits = (j && j.hits && j.hits.hits) ? j.hits.hits : [];
  attempted.push("sec_edgar");
  for(const h of hits){
    const src = h._source || {}; const id = h._id || "";
    const acc = (id.split(":")[0]||""); const file = (id.split(":")[1]||"");
    const accNo = acc.replace(/-/g,"");
    const ciks = src.ciks || (src.cik ? [src.cik] : []);
    const cikNum = ciks.length ? String(ciks[0]).replace(/^0+/,"") : "";
    const url = (cikNum && file && accNo) ? ("https://www.sec.gov/Archives/edgar/data/"+cikNum+"/"+accNo+"/"+file) : "https://www.sec.gov/cgi-bin/srqsb";
    const names = (src.display_names||[]).join(", ");
    const title = (src.form || src.file_type || "SEC Filing") + (names ? (" - "+names) : "");
    add("sec_edgar", id, title, url, "Filing "+id+" "+names+" dated "+(src.file_date||""), "sec_edgar_fulltext", (src.file_date||null));
  }
} catch(e) {}
return [{ json: {
  primary_evidence: evidence,
  sources_attempted: Array.from(new Set(attempted)),
  primary_count: evidence.length,
  t_primary_done: Date.now()
} }];

const ctx = $('Build Context').first().json;
const ev = ($json.primary_evidence) || [];
function validUrl(u){ return /^https?:\/\//i.test(u||""); }
const usable = ev.filter(e => validUrl(e.url) && (e.snippet||"").length >= 40);
const usable_count = usable.length;
const diversity = new Set(usable.map(e => e.source)).size;
const relevant = usable.filter(e => (e.adapter_score === null) || (e.adapter_score >= 0.3));
const quality_sufficient = (usable_count >= 2) && (relevant.length >= 2);
const mode = ctx.retrieval_mode;
let should_call_tavily = false;
let tavily_skip_reason = null;
if(ctx.force_tavily){ should_call_tavily = true; }
else if(mode === 'primary_only'){ should_call_tavily = false; tavily_skip_reason = 'MODE_PRIMARY_ONLY'; }
else if(quality_sufficient){ should_call_tavily = false; tavily_skip_reason = "PRIMARY_EVIDENCE_SUFFICIENT"; }
else { should_call_tavily = true; }
let reason;
if(quality_sufficient) reason = "Primary produced " + usable_count + " usable candidate(s) across " + diversity + " source(s).";
else reason = "Primary insufficient: " + usable_count + " usable candidate(s), " + relevant.length + " relevant, diversity " + diversity + ".";
return [{ json: {
  primary_evidence: ev,
  sources_attempted: $json.sources_attempted || [],
  primary_count: $json.primary_count || ev.length,
  usable_count, source_diversity: diversity, quality_sufficient,
  should_call_tavily, tavily_skip_reason, quality_reason: reason,
  t_primary_done: $json.t_primary_done || Date.now()
} }];

const ctx = $('Build Context').first().json;
const queries = (ctx.queries && ctx.queries.length) ? ctx.queries.slice(0, 3) : [ctx.normalized_claim];
const inc = ctx.tavily_include_domains || [];
const t_tavily_start = Date.now();
return queries.filter(Boolean).map(q => ({ json: {
  query: q, include_domains: inc, max_results: ctx.max_results, t_tavily_start
} }));

const ctx = $('Build Context').first().json;
const maxr = ctx.max_results || 5;
let t_tavily_start = Date.now();
const searchResults = [];
let queryCount = 0;
try {
  for(const it of $('Tavily Search').all()){
    queryCount++;
    const j = it.json || {};
    if(j.t_tavily_start) t_tavily_start = j.t_tavily_start;
    const rs = j.results || [];
    for(const r of rs){ searchResults.push({ title: r.title||"", url: r.url||"", content: r.content||"", score: (typeof r.score === "number" ? r.score : null) }); }
  }
} catch(e) {}
try { t_tavily_start = $('Split Queries').first().json.t_tavily_start || t_tavily_start; } catch(e) {}
const seen = new Set();
const deduped = [];
for(const r of searchResults){
  const key = (r.url||"").split("#")[0].replace(/\/$/,"").toLowerCase();
  if(!key || seen.has(key)) continue;
  seen.add(key); deduped.push(r);
}
deduped.sort((a,b) => (b.score||0) - (a.score||0));
const top = deduped.slice(0, Math.max(maxr, 5));
return [{ json: {
  urls: top.map(r => r.url).filter(Boolean),
  search_results: top,
  query_count: queryCount,
  search_result_count: searchResults.length,
  deduped_url_count: deduped.length,
  t_tavily_start,
  t_tavily_search_done: Date.now(),
  t_extract_start: Date.now()
} }];

const ctx = $('Build Context').first().json;
const claim = ctx.normalized_claim || ctx.claim || "";
const nowIso = new Date().toISOString();
function clean(s){ return (s||"").toString().replace(/\s+/g," ").trim(); }
const claimTokens = claim.toLowerCase().split(/[^a-z0-9]+/).filter(w => w.length > 2);
function adapterScore(text){ const t=(text||"").toLowerCase(); if(!claimTokens.length) return null; let hit=0; const seen={}; for(const w of claimTokens){ if(!seen[w]){ seen[w]=1; if(t.indexOf(w)!==-1) hit++; } } const uniq=Object.keys(seen).length; return uniq?Math.round((hit/uniq)*100)/100:null; }
const collect = $('Collect Search URLs').first().json;
const searchResults = collect.search_results || [];
const extractedByUrl = {};
let extractedCount = 0; let extractFailed = 0;
try {
  const ex = $('Tavily Extract').first().json || {};
  const rs = ex.results || [];
  for(const r of rs){ if(r.url){ extractedByUrl[r.url.replace(/\/$/,"")] = r.raw_content || r.content || ""; extractedCount++; } }
  const fr = ex.failed_results || ex.failed || [];
  extractFailed = Array.isArray(fr) ? fr.length : 0;
} catch(e) {}
const evidence = [];
for(const r of searchResults){
  const canon = (r.url||"").replace(/\/$/,"");
  const extracted = extractedByUrl[canon];
  const usedExtract = !!(extracted && extracted.length > 0);
  const content = usedExtract ? extracted : (r.content||"");
  const snip = clean(content).slice(0, 1500);
  if(!r.url && !snip) continue;
  evidence.push({
    source: "tavily_web", source_type: "WEB_FALLBACK", source_id: r.url||"",
    title: clean(r.title), url: r.url||"", snippet: snip,
    published_at: null, query_used: claim,
    retrieval_method: usedExtract ? "tavily_search_extract" : "tavily_search_snippet",
    adapter_score: (typeof r.score === "number" ? r.score : adapterScore(r.title+" "+content)),
    retrieved_at: nowIso,
    retrieval_status: usedExtract ? "success" : "extract_unavailable"
  });
}
const t_extract_done = Date.now();
const tavily = {
  called: true,
  reason: ctx.force_tavily ? 'FORCE_TAVILY' : (ctx.retrieval_mode === 'tavily_only' ? 'MODE_TAVILY_ONLY' : 'PRIMARY_EVIDENCE_INSUFFICIENT'),
  query_count: collect.query_count || 0,
  result_count: collect.search_result_count || 0,
  extracted_count: extractedCount,
  extract_failed_count: extractFailed,
  latency_ms: (t_extract_done - (collect.t_tavily_start || t_extract_done)),
  extraction_latency_ms: (t_extract_done - (collect.t_extract_start || t_extract_done))
};
return [{ json: { tavily_evidence: evidence, tavily, t_extract_done } }];

const ctx = $('Build Context').first().json;
const tEnd = Date.now();
let primaryEvidence = []; let sourcesAttempted = []; let quality = null; let tPrimaryDone = null;
try {
  const q = $('Quality Evaluation').first().json;
  primaryEvidence = q.primary_evidence || [];
  sourcesAttempted = q.sources_attempted || [];
  tPrimaryDone = q.t_primary_done || null;
  quality = { called: true, sources_attempted: sourcesAttempted, result_count: q.primary_count || primaryEvidence.length, usable_count: q.usable_count || 0, quality_sufficient: !!q.quality_sufficient, reason: q.quality_reason || "" };
} catch(e) {
  quality = { called: false, sources_attempted: [], result_count: 0, usable_count: 0, quality_sufficient: false, reason: ctx.run_primary ? 'PRIMARY_STAGE_DID_NOT_RUN' : 'SKIPPED_MODE_TAVILY_ONLY' };
}
let tavilyEvidence = []; let tavily = null;
try {
  const t = $('Normalize Tavily').first().json;
  tavilyEvidence = t.tavily_evidence || [];
  tavily = t.tavily;
} catch(e) {
  let reason = "PRIMARY_EVIDENCE_SUFFICIENT";
  try {
    const q = $('Quality Evaluation').first().json;
    if(q && q.tavily_skip_reason) reason = q.tavily_skip_reason;
  } catch(e2) {}
  tavily = { called: false, reason, query_count: 0, result_count: 0, extracted_count: 0 };
}
const primaryCount = primaryEvidence.length;
const tavilyCount = tavilyEvidence.length;
const all = primaryEvidence.concat(tavilyEvidence);
const mergedCount = all.length;
function canon(u){ return (u||"").split("#")[0].replace(/\/$/,"").toLowerCase(); }
const seenUrl = new Set(); const seenContent = new Set(); const deduped = [];
for(const e of all){
  const ku = canon(e.url);
  const kc = (e.snippet||"").toLowerCase().slice(0, 180);
  if(ku && seenUrl.has(ku)) continue;
  if(kc && seenContent.has(kc)) continue;
  if(ku) seenUrl.add(ku);
  if(kc) seenContent.add(kc);
  deduped.push(e);
}
deduped.forEach((e,i) => { e.rank = i; });
const total_latency_ms = tEnd - (ctx.t_start || tEnd);
const primary_latency_ms = (tPrimaryDone && ctx.t_start) ? (tPrimaryDone - ctx.t_start) : null;
const tavily_latency_ms = (tavily && tavily.latency_ms != null) ? tavily.latency_ms : null;
const extraction_latency_ms = (tavily && tavily.extraction_latency_ms != null) ? tavily.extraction_latency_ms : null;
const trace = [];
trace.push({ stage: "analyze", status: "success", detail: "normalized + domain routing (routing only, non-authoritative)" });
trace.push({ stage: "domain_router", status: "success", detail: ctx.domain });
if(quality.called) trace.push({ stage: "primary_retrieval", status: "success", detail: sourcesAttempted.join(", ") });
else trace.push({ stage: "primary_retrieval", status: "skipped", detail: quality.reason });
if(tavily.called) trace.push({ stage: "tavily_fallback", status: "success", detail: tavily.reason });
else trace.push({ stage: "tavily_fallback", status: "skipped", detail: tavily.reason });
trace.push({ stage: "merge_dedup", status: "success", detail: "merged " + mergedCount + " -> " + deduped.length });
return [{ json: {
  request_id: ctx.request_id,
  claim: ctx.claim,
  normalized_claim: ctx.normalized_claim,
  domain: ctx.domain,
  domain_is_routing_only: true,
  queries: ctx.queries,
  entities: ctx.entities,
  time_sensitive: ctx.time_sensitive,
  workflow_version: ctx.workflow_version,
  retrieval: {
    mode: ctx.retrieval_mode,
    primary: quality,
    tavily: tavily
  },
  evidence: deduped,
  counts: { primary: primaryCount, tavily: tavilyCount, merged: mergedCount, deduplicated: deduped.length },
  performance: { total_latency_ms, primary_latency_ms, tavily_latency_ms, extraction_latency_ms },
  trace,
  authoritative_verdict: null,
  note: "Retrieval service only. No verdict is computed by n8n. The Python HalluciGuard backend runs BGE + DeBERTa and owns the authoritative verdict."
} }];
